package in.aicon.pocket;
import android.graphics.*;import android.graphics.drawable.Drawable;
/** Original layered reflective glass preview. Static lighting, no claim of optical refraction. */
final class BlackGlass extends Drawable {
 private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private final float radius,density;private final int tint;
 BlackGlass(float radius,float density,int tint){this.radius=radius;this.density=density;this.tint=tint;}
 @Override public void draw(Canvas canvas){RectF r=new RectF(getBounds());r.inset(density,density);if(r.width()<=0||r.height()<=0)return;Path clip=new Path();clip.addRoundRect(r,radius,radius,Path.Direction.CW);canvas.save();canvas.clipPath(clip);paint.setStyle(Paint.Style.FILL);paint.setShader(new LinearGradient(r.left,r.top,r.right,r.bottom,new int[]{0xff202934,0xff0e1720,0xff030709},new float[]{0,.42f,1},Shader.TileMode.CLAMP));canvas.drawRect(r,paint);int glow=(tint&0xffffff)|0x38000000;paint.setShader(new RadialGradient(r.left+r.width()*.82f,r.top+r.height()*.8f,Math.max(r.width(),r.height())*.8f,new int[]{glow,0x00101a22},null,Shader.TileMode.CLAMP));canvas.drawRect(r,paint);paint.setShader(new LinearGradient(r.left,r.top,r.right,r.top+r.height()*.8f,new int[]{0x22ffffff,0x0cffffff,0x00ffffff},new float[]{0,.35f,1},Shader.TileMode.CLAMP));Path light=new Path();light.moveTo(r.left,r.top);light.lineTo(r.right,r.top);light.cubicTo(r.right*.82f,r.top+r.height()*.2f,r.left+r.width()*.35f,r.top+r.height()*.25f,r.left,r.top+r.height()*.75f);light.close();canvas.drawPath(light,paint);canvas.restore();paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(density*1.2f);paint.setShader(new LinearGradient(r.left,r.top,r.right,r.bottom,new int[]{0x9affffff,0x283d5868,0x6682bacd},new float[]{0,.54f,1},Shader.TileMode.CLAMP));canvas.drawRoundRect(r,radius,radius,paint);RectF inner=new RectF(r);inner.inset(density*2,density*2);paint.setStrokeWidth(density*.6f);paint.setShader(new LinearGradient(r.left,r.top,r.left,r.bottom,new int[]{0x40d5edff,0x0088aabb,0x24bedfff},null,Shader.TileMode.CLAMP));canvas.drawRoundRect(inner,Math.max(0,radius-density*2),Math.max(0,radius-density*2),paint);paint.setShader(null);paint.setStyle(Paint.Style.FILL);}
 @Override public void setAlpha(int alpha){}@Override public void setColorFilter(ColorFilter filter){}@Override public int getOpacity(){return PixelFormat.OPAQUE;}
}
